DROP PROCEDURE IF EXISTS `actualizar_estadisticas_jugador`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `actualizar_estadisticas_jugador` (IN `p_jugador_id` INT)   BEGIN
    DECLARE v_total_rayas INT;
    DECLARE v_total_juegos INT;
    DECLARE v_ganadas INT;
    DECLARE v_mano INT;
    
    SELECT COALESCE(SUM(
        CASE 
            WHEN (equipo_a_jugador1 = p_jugador_id OR equipo_a_jugador2 = p_jugador_id) AND ganador = 'A' THEN rayas
            WHEN (equipo_b_jugador1 = p_jugador_id OR equipo_b_jugador2 = p_jugador_id) AND ganador = 'B' THEN rayas
            WHEN (equipo_a_jugador1 = p_jugador_id OR equipo_a_jugador2 = p_jugador_id) AND ganador = 'B' THEN -rayas
            WHEN (equipo_b_jugador1 = p_jugador_id OR equipo_b_jugador2 = p_jugador_id) AND ganador = 'A' THEN -rayas
            ELSE 0
        END
    ), 0) INTO v_total_rayas
    FROM juegos
    WHERE equipo_a_jugador1 = p_jugador_id 
       OR equipo_a_jugador2 = p_jugador_id
       OR equipo_b_jugador1 = p_jugador_id
       OR equipo_b_jugador2 = p_jugador_id;
    
    SELECT COUNT(*) INTO v_total_juegos
    FROM juegos
    WHERE equipo_a_jugador1 = p_jugador_id 
       OR equipo_a_jugador2 = p_jugador_id
       OR equipo_b_jugador1 = p_jugador_id
       OR equipo_b_jugador2 = p_jugador_id;
    
    SELECT COUNT(*) INTO v_ganadas
    FROM juegos
    WHERE (equipo_a_jugador1 = p_jugador_id OR equipo_a_jugador2 = p_jugador_id) AND ganador = 'A'
       OR (equipo_b_jugador1 = p_jugador_id OR equipo_b_jugador2 = p_jugador_id) AND ganador = 'B';
    
    SELECT COUNT(*) INTO v_mano
    FROM juegos
    WHERE jugador_mano_id = p_jugador_id;
    
    INSERT INTO estadisticas_jugadores 
        (jugador_id, total_rayas, total_juegos, partidas_ganadas, partidas_perdidas, veces_mano, promedio_rayas_por_juego)
    VALUES 
        (p_jugador_id, v_total_rayas, v_total_juegos, v_ganadas, 
         v_total_juegos - v_ganadas, v_mano,
         IF(v_total_juegos > 0, v_total_rayas / v_total_juegos, 0))
    ON DUPLICATE KEY UPDATE
        total_rayas = VALUES(total_rayas),
        total_juegos = VALUES(total_juegos),
        partidas_ganadas = VALUES(partidas_ganadas),
        partidas_perdidas = VALUES(partidas_perdidas),
        veces_mano = VALUES(veces_mano),
        promedio_rayas_por_juego = VALUES(promedio_rayas_por_juego),
        ultima_actualizacion = NOW();
END$$

DROP PROCEDURE IF EXISTS `actualizar_estadisticas_jugador_por_grupo`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `actualizar_estadisticas_jugador_por_grupo` (IN `p_jugador_id` INT, IN `p_grupo_id` INT)   BEGIN
    DECLARE v_total_rayas INT;
    DECLARE v_total_juegos INT;
    DECLARE v_ganadas INT;
    DECLARE v_mano INT;
    
    -- Calcular rayas totales del jugador en el grupo específico
    SELECT COALESCE(SUM(
        CASE 
            WHEN (jg.equipo_a_jugador1 = p_jugador_id OR jg.equipo_a_jugador2 = p_jugador_id) AND jg.ganador = 'A' THEN jg.rayas
            WHEN (jg.equipo_b_jugador1 = p_jugador_id OR jg.equipo_b_jugador2 = p_jugador_id) AND jg.ganador = 'B' THEN jg.rayas
            WHEN (jg.equipo_a_jugador1 = p_jugador_id OR jg.equipo_a_jugador2 = p_jugador_id) AND jg.ganador = 'B' THEN -jg.rayas
            WHEN (jg.equipo_b_jugador1 = p_jugador_id OR jg.equipo_b_jugador2 = p_jugador_id) AND jg.ganador = 'A' THEN -jg.rayas
            ELSE 0
        END
    ), 0) INTO v_total_rayas
    FROM juegos jg
    WHERE jg.grupo_id = p_grupo_id
      AND (jg.equipo_a_jugador1 = p_jugador_id 
        OR jg.equipo_a_jugador2 = p_jugador_id
        OR jg.equipo_b_jugador1 = p_jugador_id
        OR jg.equipo_b_jugador2 = p_jugador_id);
    
    -- Calcular total de juegos
    SELECT COUNT(*) INTO v_total_juegos
    FROM juegos jg
    WHERE jg.grupo_id = p_grupo_id
      AND (jg.equipo_a_jugador1 = p_jugador_id 
        OR jg.equipo_a_jugador2 = p_jugador_id
        OR jg.equipo_b_jugador1 = p_jugador_id
        OR jg.equipo_b_jugador2 = p_jugador_id);
    
    -- Calcular partidas ganadas
    SELECT COUNT(*) INTO v_ganadas
    FROM juegos jg
    WHERE jg.grupo_id = p_grupo_id
      AND ((jg.equipo_a_jugador1 = p_jugador_id OR jg.equipo_a_jugador2 = p_jugador_id) AND jg.ganador = 'A')
       OR ((jg.equipo_b_jugador1 = p_jugador_id OR jg.equipo_b_jugador2 = p_jugador_id) AND jg.ganador = 'B');
    
    -- Calcular veces que fue mano
    SELECT COUNT(*) INTO v_mano
    FROM juegos jg
    WHERE jg.grupo_id = p_grupo_id
      AND jg.jugador_mano_id = p_jugador_id;
    
    -- Insertar o actualizar estadísticas
    INSERT INTO estadisticas_jugadores 
        (jugador_id, grupo_id, total_rayas, total_juegos, partidas_ganadas, partidas_perdidas, veces_mano, promedio_rayas_por_juego)
    VALUES 
        (p_jugador_id, p_grupo_id, v_total_rayas, v_total_juegos, v_ganadas, 
         v_total_juegos - v_ganadas, v_mano,
         IF(v_total_juegos > 0, v_total_rayas / v_total_juegos, 0))
    ON DUPLICATE KEY UPDATE
        total_rayas = VALUES(total_rayas),
        total_juegos = VALUES(total_juegos),
        partidas_ganadas = VALUES(partidas_ganadas),
        partidas_perdidas = VALUES(partidas_perdidas),
        veces_mano = VALUES(veces_mano),
        promedio_rayas_por_juego = VALUES(promedio_rayas_por_juego),
        ultima_actualizacion = NOW();
END$$

DROP PROCEDURE IF EXISTS `actualizar_todas_estadisticas`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `actualizar_todas_estadisticas` ()   BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_jugador_id INT;
    DECLARE cur CURSOR FOR SELECT id FROM jugadores WHERE activo = TRUE;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO v_jugador_id;
        IF done THEN
            LEAVE read_loop;
        END IF;
        CALL actualizar_estadisticas_jugador(v_jugador_id);
    END LOOP;
    CLOSE cur;
END$$

DROP PROCEDURE IF EXISTS `actualizar_todas_estadisticas_grupo`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `actualizar_todas_estadisticas_grupo` (IN `p_grupo_id` INT)   BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_jugador_id INT;
    DECLARE cur CURSOR FOR 
        SELECT jugador_id FROM grupo_jugadores 
        WHERE grupo_id = p_grupo_id AND activo = 1;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO v_jugador_id;
        IF done THEN
            LEAVE read_loop;
        END IF;
        CALL actualizar_estadisticas_jugador_por_grupo(v_jugador_id, p_grupo_id);
    END LOOP;
    CLOSE cur;
END$$

DROP PROCEDURE IF EXISTS `agregar_jugador_a_grupo`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `agregar_jugador_a_grupo` (IN `p_grupo_id` INT, IN `p_jugador_id` INT)   BEGIN
    INSERT INTO grupo_jugadores (grupo_id, jugador_id, activo, fecha_ingreso)
    VALUES (p_grupo_id, p_jugador_id, 1, NOW())
    ON DUPLICATE KEY UPDATE activo = 1, fecha_ingreso = NOW();
    
    -- Crear estadísticas iniciales si no existen
    INSERT INTO estadisticas_jugadores (jugador_id, grupo_id, total_rayas, total_juegos, partidas_ganadas, partidas_perdidas, veces_mano, promedio_rayas_por_juego)
    VALUES (p_jugador_id, p_grupo_id, 0, 0, 0, 0, 0, 0)
    ON DUPLICATE KEY UPDATE jugador_id = jugador_id;
END$$

DROP PROCEDURE IF EXISTS `eliminar_jugador_de_grupo`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `eliminar_jugador_de_grupo` (IN `p_grupo_id` INT, IN `p_jugador_id` INT)   BEGIN
    UPDATE grupo_jugadores SET activo = 0 WHERE grupo_id = p_grupo_id AND jugador_id = p_jugador_id;
    
    -- Opcional: mantener estadísticas históricas, solo marcar como inactivo
END$$

DROP PROCEDURE IF EXISTS `obtener_estadisticas_parejas`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `obtener_estadisticas_parejas` ()   BEGIN
    SELECT 
        j1.id as jugador1_id,
        j1.nombre as jugador1_nombre,
        j1.avatar_url as jugador1_img,
        j2.id as jugador2_id,
        j2.nombre as jugador2_nombre,
        j2.avatar_url as jugador2_img,
        COUNT(*) as veces_jugadas,
        SUM(CASE 
            WHEN (jg.equipo_a_jugador1 IN (j1.id, j2.id) AND jg.equipo_a_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'A') 
                OR (jg.equipo_b_jugador1 IN (j1.id, j2.id) AND jg.equipo_b_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'B')
            THEN 1 ELSE 0 END) as victorias,
        SUM(CASE 
            WHEN (jg.equipo_a_jugador1 IN (j1.id, j2.id) AND jg.equipo_a_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'A') 
                OR (jg.equipo_b_jugador1 IN (j1.id, j2.id) AND jg.equipo_b_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'B')
            THEN jg.rayas ELSE 0 END) as rayas_ganadas,
        SUM(CASE 
            WHEN (jg.equipo_a_jugador1 IN (j1.id, j2.id) AND jg.equipo_a_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'B') 
                OR (jg.equipo_b_jugador1 IN (j1.id, j2.id) AND jg.equipo_b_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'A')
            THEN jg.rayas ELSE 0 END) as rayas_perdidas
    FROM jugadores j1
    JOIN jugadores j2 ON j1.id < j2.id
    LEFT JOIN juegos jg ON 
        (jg.equipo_a_jugador1 IN (j1.id, j2.id) AND jg.equipo_a_jugador2 IN (j1.id, j2.id))
        OR (jg.equipo_b_jugador1 IN (j1.id, j2.id) AND jg.equipo_b_jugador2 IN (j1.id, j2.id))
    WHERE j1.activo = 1 AND j2.activo = 1
    GROUP BY j1.id, j2.id
    HAVING veces_jugadas > 0
    ORDER BY victorias DESC, rayas_ganadas DESC;
END$$

DROP PROCEDURE IF EXISTS `obtener_estadisticas_parejas_por_grupo`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `obtener_estadisticas_parejas_por_grupo` (IN `p_grupo_id` INT)   BEGIN
    SELECT 
        j1.id as jugador1_id,
        j1.nombre as jugador1_nombre,
        COALESCE(j1.avatar_url, '') as jugador1_img,
        j2.id as jugador2_id,
        j2.nombre as jugador2_nombre,
        COALESCE(j2.avatar_url, '') as jugador2_img,
        COUNT(*) as veces_jugadas,
        SUM(CASE 
            WHEN (jg.equipo_a_jugador1 IN (j1.id, j2.id) AND jg.equipo_a_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'A') 
                OR (jg.equipo_b_jugador1 IN (j1.id, j2.id) AND jg.equipo_b_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'B')
            THEN 1 ELSE 0 END) as victorias,
        SUM(CASE 
            WHEN (jg.equipo_a_jugador1 IN (j1.id, j2.id) AND jg.equipo_a_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'A') 
                OR (jg.equipo_b_jugador1 IN (j1.id, j2.id) AND jg.equipo_b_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'B')
            THEN jg.rayas ELSE 0 END) as rayas_ganadas,
        SUM(CASE 
            WHEN (jg.equipo_a_jugador1 IN (j1.id, j2.id) AND jg.equipo_a_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'B') 
                OR (jg.equipo_b_jugador1 IN (j1.id, j2.id) AND jg.equipo_b_jugador2 IN (j1.id, j2.id) AND jg.ganador = 'A')
            THEN jg.rayas ELSE 0 END) as rayas_perdidas
    FROM grupo_jugadores gj1
    JOIN grupo_jugadores gj2 ON gj1.grupo_id = gj2.grupo_id AND gj1.grupo_id = p_grupo_id AND gj1.jugador_id < gj2.jugador_id
    JOIN jugadores j1 ON gj1.jugador_id = j1.id
    JOIN jugadores j2 ON gj2.jugador_id = j2.id
    INNER JOIN juegos jg ON jg.grupo_id = p_grupo_id
        AND ((jg.equipo_a_jugador1 IN (j1.id, j2.id) AND jg.equipo_a_jugador2 IN (j1.id, j2.id))
          OR (jg.equipo_b_jugador1 IN (j1.id, j2.id) AND jg.equipo_b_jugador2 IN (j1.id, j2.id)))
    WHERE gj1.activo = 1 AND gj2.activo = 1
    GROUP BY j1.id, j2.id
    ORDER BY victorias DESC, rayas_ganadas DESC;
END$$

DROP PROCEDURE IF EXISTS `obtener_historial_por_grupo`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `obtener_historial_por_grupo` (IN `p_grupo_id` INT)   BEGIN
    SELECT 
        p.id,
        p.tipo_ronda as tipo,
        DATE_FORMAT(p.fecha_inicio, '%Y-%m-%d %H:%i:%s') as fecha,
        DATE_FORMAT(p.fecha_fin, '%Y-%m-%d %H:%i:%s') as fechaFin,
        p.num_ronda as numRonda,
        p.estado,
        (SELECT JSON_ARRAYAGG(
            JSON_OBJECT(
                'id', j.id,
                'n', j.nombre,
                'r', COALESCE(pj.rayas_finales, 0),
                'jj', COALESCE(pj.juegos_jugados, 0),
                'img', j.avatar_url,
                'email', j.email,
                'phone', j.telefono
            )
        ) FROM partida_jugadores pj 
          JOIN jugadores j ON pj.jugador_id = j.id 
          WHERE pj.partida_id = p.id) as jugadores,
        (SELECT JSON_ARRAYAGG(
            JSON_OBJECT(
                'j', jg.num_juego,
                'numRonda', jg.num_ronda,
                'ptsW', jg.puntos_equipo_a,
                'ptsL', jg.puntos_equipo_b,
                'r', jg.rayas,
                'gan', (
                    SELECT JSON_ARRAYAGG(ja.nombre) FROM jugadores ja 
                    WHERE ja.id IN (jg.equipo_a_jugador1, jg.equipo_a_jugador2) AND jg.ganador = 'A'
                       OR ja.id IN (jg.equipo_b_jugador1, jg.equipo_b_jugador2) AND jg.ganador = 'B'
                ),
                'per', (
                    SELECT JSON_ARRAYAGG(ja.nombre) FROM jugadores ja 
                    WHERE ja.id IN (jg.equipo_a_jugador1, jg.equipo_a_jugador2) AND jg.ganador = 'B'
                       OR ja.id IN (jg.equipo_b_jugador1, jg.equipo_b_jugador2) AND jg.ganador = 'A'
                ),
                'mano', (SELECT nombre FROM jugadores WHERE id = jg.jugador_mano_id),
                'resting', (
                    SELECT JSON_ARRAYAGG(ja.nombre) FROM jugadores ja 
                    WHERE ja.id IN (jg.descanso_jugador1, jg.descanso_jugador2) AND ja.id IS NOT NULL
                )
            )
        ) FROM juegos jg WHERE jg.partida_id = p.id) as log
    FROM partidas p
    WHERE p.grupo_id = p_grupo_id
    ORDER BY p.fecha_inicio DESC;
END$$

DROP PROCEDURE IF EXISTS `obtener_jugadores_por_grupo`$$
CREATE DEFINER=`domino_app`@`localhost` PROCEDURE `obtener_jugadores_por_grupo` (IN `p_grupo_id` INT)   BEGIN
    SELECT 
        j.id,
        j.nombre,
        j.email,
        j.telefono,
        j.avatar_url,
        gj.fecha_ingreso,
        gj.activo as activo_en_grupo
    FROM grupo_jugadores gj
    JOIN jugadores j ON gj.jugador_id = j.id
    WHERE gj.grupo_id = p_grupo_id AND gj.activo = 1 AND j.activo = 1
    ORDER BY j.nombre;
END$$

DELIMITER ;

