--
-- Estructura de tabla para la tabla `juegos`
--

DROP TABLE IF EXISTS `juegos`;
CREATE TABLE IF NOT EXISTS `juegos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `partida_id` int NOT NULL,
  `grupo_id` int DEFAULT NULL,
  `num_juego` int NOT NULL,
  `num_ronda` int DEFAULT '1',
  `equipo_a_jugador1` int DEFAULT NULL,
  `equipo_a_jugador2` int DEFAULT NULL,
  `equipo_b_jugador1` int DEFAULT NULL,
  `equipo_b_jugador2` int DEFAULT NULL,
  `jugador_mano_id` int DEFAULT NULL,
  `puntos_equipo_a` int DEFAULT '0',
  `puntos_equipo_b` int DEFAULT '0',
  `ganador` enum('A','B') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `rayas` int NOT NULL,
  `descanso_jugador1` int DEFAULT NULL,
  `descanso_jugador2` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `partida_id` (`partida_id`),
  KEY `equipo_a_jugador1` (`equipo_a_jugador1`),
  KEY `equipo_a_jugador2` (`equipo_a_jugador2`),
  KEY `equipo_b_jugador1` (`equipo_b_jugador1`),
  KEY `equipo_b_jugador2` (`equipo_b_jugador2`),
  KEY `jugador_mano_id` (`jugador_mano_id`),
  KEY `idx_juegos_grupo` (`grupo_id`)
) ENGINE=MyISAM AUTO_INCREMENT=398 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

