--
-- Estructura para la vista `estadisticas_resumen_grupo`
--
DROP TABLE IF EXISTS `estadisticas_resumen_grupo`;

DROP VIEW IF EXISTS `estadisticas_resumen_grupo`;
CREATE ALGORITHM=UNDEFINED DEFINER=`domino_app`@`localhost` SQL SECURITY DEFINER VIEW `estadisticas_resumen_grupo`  AS SELECT `g`.`id` AS `grupo_id`, `g`.`nombre` AS `grupo_nombre`, `g`.`logo_url` AS `grupo_logo`, count(distinct `gj`.`jugador_id`) AS `total_jugadores`, count(distinct `p`.`id`) AS `total_partidas`, count(distinct `jg`.`id`) AS `total_juegos`, coalesce(sum(`e`.`total_rayas`),0) AS `total_rayas_grupo`, coalesce(sum(`e`.`total_juegos`),0) AS `total_juegos_jugados`, (select count(0) from `usuarios` `u` where ((`u`.`grupo_id` = `g`.`id`) and (`u`.`activo` = 1))) AS `total_usuarios` FROM (((((`grupos` `g` left join `grupo_jugadores` `gj` on(((`g`.`id` = `gj`.`grupo_id`) and (`gj`.`activo` = 1)))) left join `jugadores` `j` on((`gj`.`jugador_id` = `j`.`id`))) left join `estadisticas_jugadores` `e` on(((`e`.`jugador_id` = `j`.`id`) and (`e`.`grupo_id` = `g`.`id`)))) left join `partidas` `p` on((`p`.`grupo_id` = `g`.`id`))) left join `juegos` `jg` on((`jg`.`grupo_id` = `g`.`id`))) WHERE (`g`.`activo` = 1) GROUP BY `g`.`id` ;

