--
-- Estructura para la vista `historial_completo`
--
DROP TABLE IF EXISTS `historial_completo`;

DROP VIEW IF EXISTS `historial_completo`;
CREATE ALGORITHM=UNDEFINED DEFINER=`domino_app`@`localhost` SQL SECURITY DEFINER VIEW `historial_completo`  AS SELECT `p`.`id` AS `partida_id`, `p`.`fecha_inicio` AS `fecha_inicio`, `p`.`tipo_ronda` AS `tipo_ronda`, `j`.`num_juego` AS `num_juego`, `ja1`.`nombre` AS `jugador_a1`, `ja2`.`nombre` AS `jugador_a2`, `jb1`.`nombre` AS `jugador_b1`, `jb2`.`nombre` AS `jugador_b2`, `j`.`puntos_equipo_a` AS `puntos_equipo_a`, `j`.`puntos_equipo_b` AS `puntos_equipo_b`, `j`.`ganador` AS `ganador`, `j`.`rayas` AS `rayas`, `jm`.`nombre` AS `jugador_mano` FROM ((((((`partidas` `p` join `juegos` `j` on((`p`.`id` = `j`.`partida_id`))) left join `jugadores` `ja1` on((`j`.`equipo_a_jugador1` = `ja1`.`id`))) left join `jugadores` `ja2` on((`j`.`equipo_a_jugador2` = `ja2`.`id`))) left join `jugadores` `jb1` on((`j`.`equipo_b_jugador1` = `jb1`.`id`))) left join `jugadores` `jb2` on((`j`.`equipo_b_jugador2` = `jb2`.`id`))) left join `jugadores` `jm` on((`j`.`jugador_mano_id` = `jm`.`id`))) ORDER BY `p`.`fecha_inicio` DESC, `j`.`num_juego` ASC ;

