--
-- Estructura para la vista `ranking_general`
--
DROP TABLE IF EXISTS `ranking_general`;

DROP VIEW IF EXISTS `ranking_general`;
CREATE ALGORITHM=UNDEFINED DEFINER=`domino_app`@`localhost` SQL SECURITY DEFINER VIEW `ranking_general`  AS SELECT `j`.`id` AS `id`, `j`.`nombre` AS `nombre`, `j`.`avatar_url` AS `avatar_url`, coalesce(`e`.`total_rayas`,0) AS `rayas_totales`, coalesce(`e`.`total_juegos`,0) AS `juegos_totales`, coalesce(`e`.`partidas_ganadas`,0) AS `victorias`, coalesce(`e`.`partidas_perdidas`,0) AS `derrotas`, coalesce(`e`.`veces_mano`,0) AS `veces_mano`, coalesce(`e`.`promedio_rayas_por_juego`,0) AS `promedio_rayas` FROM (`jugadores` `j` left join `estadisticas_jugadores` `e` on((`j`.`id` = `e`.`jugador_id`))) WHERE (`j`.`activo` = 1) ORDER BY coalesce(`e`.`total_rayas`,0) DESC ;

