--
-- Estructura para la vista `ranking_por_grupo`
--
DROP TABLE IF EXISTS `ranking_por_grupo`;

DROP VIEW IF EXISTS `ranking_por_grupo`;
CREATE ALGORITHM=UNDEFINED DEFINER=`domino_app`@`localhost` SQL SECURITY DEFINER VIEW `ranking_por_grupo`  AS SELECT `g`.`id` AS `grupo_id`, `g`.`nombre` AS `grupo_nombre`, `g`.`logo_url` AS `grupo_logo`, `j`.`id` AS `jugador_id`, `j`.`nombre` AS `jugador_nombre`, `j`.`avatar_url` AS `jugador_avatar`, coalesce(`e`.`total_rayas`,0) AS `total_rayas`, coalesce(`e`.`total_juegos`,0) AS `total_juegos`, coalesce(`e`.`partidas_ganadas`,0) AS `partidas_ganadas`, coalesce(`e`.`partidas_perdidas`,0) AS `partidas_perdidas`, coalesce(`e`.`veces_mano`,0) AS `veces_mano`, coalesce(`e`.`promedio_rayas_por_juego`,0) AS `promedio_rayas` FROM (((`grupos` `g` join `grupo_jugadores` `gj` on(((`g`.`id` = `gj`.`grupo_id`) and (`gj`.`activo` = 1)))) join `jugadores` `j` on(((`gj`.`jugador_id` = `j`.`id`) and (`j`.`activo` = 1)))) left join `estadisticas_jugadores` `e` on(((`e`.`jugador_id` = `j`.`id`) and (`e`.`grupo_id` = `g`.`id`)))) WHERE (`g`.`activo` = 1) ORDER BY `g`.`nombre` ASC, coalesce(`e`.`total_rayas`,0) DESC ;
COMMIT;

